@Override
public String toString() {
    String str = "TikaInputStream of ";
    if (hasFile()) {
        try {
            str += getPath().toString();
        } catch (IOException e) {
            str += "unknown path";
        }
    } else {
        str += in.toString();
    }
    if (openContainer != null) {
        str += " (in " + openContainer + ")";
    }
    return str;
}
